-- SQL DDL for ClickHouse, generated by ormbridge.

CREATE TABLE authors (
  id UUID DEFAULT generateUUIDv4(),
  handle String,
  favourite_book_id Nullable(Int32),
  latest_book_id Nullable(Int64)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE books (
  id Int64,
  title String,
  tags Array(String) DEFAULT [],
  grid Array(Array(Int32)),
  colors Array(Enum8('red' = 1, 'green' = 2)),
  color Enum8('red' = 1, 'green' = 2) DEFAULT 'red',
  price Decimal(8, 2) DEFAULT 9.99,
  settings String DEFAULT '{"theme": "dark", "tabs": [1, 2]}' COMMENT 'JSON document',
  published_on Date32 DEFAULT today(),
  opens_at Nullable(String) COMMENT 'time of day (HH:MM:SS)',
  released_at Nullable(DateTime64(3)) DEFAULT '2020-01-02 03:04:05',
  pages Int32 DEFAULT 100,
  ratio Float64 DEFAULT 0.5,
  in_print Bool DEFAULT true,
  notes Nullable(String),
  `window` Nullable(String) COMMENT 'range stored as text',
  extra Map(String, String),
  read_time Nullable(Int64) COMMENT 'duration in microseconds',
  cover Nullable(String) COMMENT 'binary data',
  author_id UUID,
  editor_id Nullable(UUID),
  series_handle Nullable(String),
  INDEX books_title_author_id_idx (title, author_id) TYPE set(100) GRANULARITY 4,
  INDEX books_published_idx published_on TYPE minmax GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE series (
  id Int32,
  handle String,
  parent_id Nullable(Int32)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE audiobooks (
  minutes Int32,
  book_ptr_id Int64
)
ENGINE = MergeTree()
ORDER BY (book_ptr_id)
PRIMARY KEY (book_ptr_id);

CREATE TABLE index_rows (
  id Int32,
  `sql` Nullable(String),
  class Nullable(String),
  `table` Nullable(Int32)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE tagged (
  id Int64
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE tagged_books (
  id Int32,
  tagged_id Int64,
  book_id Int64,
  INDEX tagged_books_tagged_id_book_id_idx (tagged_id, book_id) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id)
COMMENT 'many-to-many join table';
